// ============================================================================
// Error types — payment completion
// ============================================================================

/** Thrown when a repair is not in 'ready' status and cannot be completed. */
export class RepairNotReadyError extends Error {
  constructor(public readonly currentStatus: string) {
    super(`Repair must be in 'ready' status to complete, currently '${currentStatus}'`)
    this.name = 'RepairNotReadyError'
  }
}

/** Thrown when payment total does not match the repair line item totals. */
export class PaymentMismatchError extends Error {
  constructor(
    public readonly expected: number,
    public readonly received: number,
  ) {
    super(`Payment total mismatch: expected ${expected} cents, received ${received} cents`)
    this.name = 'PaymentMismatchError'
  }
}

/** Thrown when stock is insufficient for parts used in a repair. */
export class InsufficientStockForRepairError extends Error {
  constructor(public readonly shortfalls: Array<{ partId: string; requested: number; available: number }>) {
    super(`Insufficient stock for ${shortfalls.length} part(s) in repair`)
    this.name = 'InsufficientStockForRepairError'
  }
}

// ============================================================================
// Payment Completion Result Type
// ============================================================================

/** Result returned after successful repair payment completion */
export interface CompleteRepairResult {
  /** The updated repair record with completedAt set */
  repair: {
    id: string
    bicycleId: string
    assignedTo: string | null
    status: RepairStatus
    customerNotes: string | null
    internalNotes: string | null
    holdReason: HoldReason | null
    holdReasonNote: string | null
    plannedDate: number | null
    pickupDate: number | null
    completedAt: number | null
    createdAt: number
  }
  /** The linked sale record created for revenue attribution */
  sale: {
    id: string
    saleNumber: string
    customerId: string | null
    sourceType: 'direct_sale' | 'repair' | 'customer_order' | 'backorder'
    sourceId: string | null
    status: 'completed' | 'voided'
    subtotalNet: number
    vatTotal: number
    totalGross: number
  }
  /** All payments created for this completion */
  payments: Array<{
    id: string
    method: 'cash' | 'card' | 'bank_transfer'
    amount: number
  }>
  /** Stock movements created for parts used */
  stockMovements: Array<{
    id: string
    partId: string
    quantityDelta: number
    reason: string
    referenceType: string
    referenceId: string
  }>
}

/** Input for completing a repair with payment data (single or split) */
export interface CompleteRepairPaymentInput {
  /** Array of payment methods — single entry for single-payment, multiple for split */
  payments: Array<{
    method: 'cash' | 'card'
    amount: number
  }>
}

// ============================================================================
// Stock validation for repair completion (aggregates from stock_movements)
// ============================================================================

/** Input: one part with a requested quantity to validate. */
interface RepairStockCheckRequest {
  /** Part ID to check availability for */
  partId: string
  /** Number of units the repair uses */
  requestedQuantity: number
}

/** One part that does not have enough stock in the context of a repair completion. */
interface RepairShortfallDetail {
  /** The part ID with insufficient stock */
  partId: string
  /** How many units were requested by the repair line items */
  requested: number
  /** How many units are actually available (computed from movements) */
  available: number
}

/** Result of validating a batch of stock requests for repair completion. */
interface RepairStockValidationResult {
  /** true if every part has sufficient stock; false otherwise */
  valid: boolean
  /** Non-empty only when valid is false — lists each short-falling part */
  shortfalls: RepairShortfallDetail[]
}

/**
 * Validate whether requested quantities are available in stock for repair completion.
 *
 * Computes available stock per part by summing `quantityDelta` from the
 * `stock_movements` table — never trusts denormalized `quantityOnHand`.
 */
async function validateRepairStockAvailability(
  requests: RepairStockCheckRequest[]
): Promise<RepairStockValidationResult> {
  if (requests.length === 0) {
    return { valid: true, shortfalls: [] }
  }

  const partIds = [...new Set(requests.map(r => r.partId))]

  const aggregationQuery = db
    .select({
      partId: stockMovements.partId,
      totalDelta: sql<number>`COALESCE(${sum(stockMovements.quantityDelta)}, 0)`
    })
    .from(stockMovements)
    .where(inArray(stockMovements.partId, partIds))
    .groupBy(stockMovements.partId)

  const aggregationResults = await aggregationQuery

  const availableMap = new Map<string, number>()
  for (const row of aggregationResults) {
    availableMap.set(row.partId, Number(row.totalDelta))
  }

  const shortfalls: RepairShortfallDetail[] = []
  for (const req of requests) {
    const available = availableMap.get(req.partId) ?? 0
    if (req.requestedQuantity > available) {
      shortfalls.push({
        partId: req.partId,
        requested: req.requestedQuantity,
        available
      })
    }
  }

  shortfalls.sort((a, b) => a.partId.localeCompare(b.partId))

  return {
    valid: shortfalls.length === 0,
    shortfalls
  }
}

